import { createTheme } from '@mui/material/styles';
import { purple } from '@mui/material/colors';


const theme = createTheme ({
    palette: {
        primary: {
            main:'#8C6872',
            blushPInk: '#D9BAC9',
            stone: '#D9D8D7',
            choco: '#8C5946',
            coffee: '#592C22',
        },
        secondary: {
           main: '#D9BAC9'
        },  
        
        navlink: {
            secondary: '#D9D8D7'
        },

        footer: {
            main: '#592C22',
            contrastText: '#D9D8D7',

        }
    },
    typography: {
        h3: {
            fontSize: '34px',
            fontFamily: 'Segoe UI',
            fontWeight: '600',
            color: 'grey[400]',
        }
    }
});


export default theme;
